import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"远游·远游","description":"","frontmatter":{"title":"远游·远游","date":"2026-11-24T00:00:00.000Z","seq":23,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"悲回风","link":"/blogs/楚辞/悲回风.html"},"next":{"text":"卜居","link":"/blogs/楚辞/卜居.html"}},"headers":[],"relativePath":"blogs/楚辞/远游·远游.md","filePath":"blogs/楚辞/远游·远游.md"}'),o={name:"blogs/楚辞/远游·远游.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="远游·远游" tabindex="-1">远游·远游 <a class="header-anchor" href="#远游·远游" aria-label="Permalink to &quot;远游·远游&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　远游</p><div class="poem"><p class="poem-stanza">悲时俗之迫阨兮，愿轻举而远游。</p><p class="poem-stanza">质菲薄而无因兮，焉讬乘而上浮？</p><p class="poem-stanza">遭沈浊而污秽兮，独郁结其谁语！</p><p class="poem-stanza">夜耿耿而不寐兮，魂营营而至曙。</p><p class="poem-stanza">惟天地之无穷兮，哀人生之长勤。</p><p class="poem-stanza">往者余弗及兮，来者吾不闻。</p><p class="poem-stanza">步徙倚而遥思兮，怊惝怳而乖怀。</p><p class="poem-stanza">意荒忽而流荡兮，心愁悽而增悲。</p><p class="poem-stanza">神倏忽而不反兮，形枯槁而独留。</p><p class="poem-stanza">内惟省以操端兮，求正气之所由。</p><p class="poem-stanza">漠虚静以恬愉兮，澹无为而自得。</p><p class="poem-stanza">闻赤松之清尘兮，愿承风乎遗则。</p><p class="poem-stanza">贵真人之休德兮，美往世之登仙</p><p class="poem-stanza">与化去而不见兮，名声著而日延。</p><p class="poem-stanza">奇傅说之讬辰星兮，羡韩众之得一。</p><p class="poem-stanza">形穆穆以浸远兮，离人群而遁逸。</p><p class="poem-stanza">因气变而遂曾举兮，忽神奔而鬼怪。</p><p class="poem-stanza">时仿佛以遥见兮，精晈晈以往来。</p><p class="poem-stanza">超氛埃而淑邮兮，终不反其故都。</p><p class="poem-stanza">免众患而不惧兮，世莫知其所如。</p><p class="poem-stanza">恐天时之代序兮，耀灵晔而西征。</p><p class="poem-stanza">微霜降而下沦兮，悼芳草之先蘦。</p><p class="poem-stanza">聊仿佯而逍遥兮，永历年而无成。</p><p class="poem-stanza">谁可与玩斯遗芳兮？</p><p class="poem-stanza">长向风而舒情。</p><p class="poem-stanza">高阳邈以远兮，余将焉所程？</p><p class="poem-stanza">重曰：</p><p class="poem-stanza">春秋忽其不淹兮，奚久留此故居。</p><p class="poem-stanza">轩辕不可攀援兮，吾将从王乔而娱戏。</p><p class="poem-stanza">餐六气而饮沆瀣兮，漱正阳而含朝霞。</p><p class="poem-stanza">保神明之清澄兮，精气入而麤秽除。</p><p class="poem-stanza">顺凯风以从游兮，至南巢而壹息。</p><p class="poem-stanza">见王子而宿之兮，审壹气之和德。</p><p class="poem-stanza">曰“道可受兮，不可传</p><p class="poem-stanza">其小无内兮，其大无垠。</p><p class="poem-stanza">毋滑而魂兮，彼将自然</p><p class="poem-stanza">壹气孔神兮，于中夜存。</p><p class="poem-stanza">虚以待之存，无为之先</p><p class="poem-stanza">庶类以成兮，此德之门。”</p><p class="poem-stanza">闻至贵而遂徂兮，忽乎吾将行。</p><p class="poem-stanza">仍羽人于丹丘，留不死之旧乡。</p><p class="poem-stanza">朝濯发于汤谷兮，夕晞余身兮九阳。</p><p class="poem-stanza">吸飞泉之微液兮，怀琬琰之华英。</p><p class="poem-stanza">玉色頩以脕颜兮，精醇粹而始壮。</p><p class="poem-stanza">质销铄以汋约兮，神要眇以淫放。</p><p class="poem-stanza">嘉南州之炎德兮，丽桂树之冬荣</p><p class="poem-stanza">山萧条而无兽兮，野寂漠其无人。</p><p class="poem-stanza">载营魄而登霞兮，掩浮云而上征。</p><p class="poem-stanza">命天阍其开关兮，排阊阖而望予。</p><p class="poem-stanza">召丰隆使先导兮，问太微之所居。</p><p class="poem-stanza">集重阳入帝宫兮，造旬始而观清都。</p><p class="poem-stanza">朝发轫于太仪兮，夕始临乎于微闾。</p><p class="poem-stanza">屯余车之万乘兮，纷容与而并驰。</p><p class="poem-stanza">驾八龙之婉婉兮，载云旗之逶蛇。</p><p class="poem-stanza">建雄虹之采旄兮，五色杂而炫耀。</p><p class="poem-stanza">服偃蹇以低昂兮，骖连蜷以骄骜。</p><p class="poem-stanza">骑胶葛以杂乱兮，斑漫衍而方行。</p><p class="poem-stanza">撰余辔而正策兮，吾将过乎句芒。</p><p class="poem-stanza">历太皓以右转兮，前飞廉以启路。</p><p class="poem-stanza">阳杲杲其未光兮，凌天地以径度。</p><p class="poem-stanza">风伯为余先驱兮，氛埃辟而清凉。</p><p class="poem-stanza">凤凰翼其承旂兮，遇蓐收乎西皇。</p><p class="poem-stanza">揽慧星以为旍兮，举斗柄以为麾。</p><p class="poem-stanza">叛陆离其上下兮，游惊雾之流波。</p><p class="poem-stanza">时暧曃其曭莽兮，召玄武而奔属。</p><p class="poem-stanza">后文昌使掌行兮，选署众神以并轂。</p><p class="poem-stanza">路漫漫其修远兮，徐弭节而高厉。</p><p class="poem-stanza">左雨师使径侍兮，右雷公以为卫。</p><p class="poem-stanza">欲度世以忘归兮，意姿睢以抯挢。</p><p class="poem-stanza">内欣欣而自美兮，聊媮娱以淫乐。</p><p class="poem-stanza">涉青云以汎滥游兮，忽临睨夫旧乡。</p><p class="poem-stanza">仆夫怀余心悲兮，边马顾而不行。</p><p class="poem-stanza">思旧故以想象兮，长太息而掩涕。</p><p class="poem-stanza">汜容与而遐举兮，聊抑志而自弭。</p><p class="poem-stanza">指炎神而直驰兮，吾将往乎南疑。</p><p class="poem-stanza">览方外之荒忽兮，沛罔瀁而自浮。</p><p class="poem-stanza">祝融戒而跸御兮，腾告鸾鸟迎宓妃。</p><p class="poem-stanza">张咸池奏承云兮，二女御九韶歌。</p><p class="poem-stanza">使湘灵鼓瑟兮，令海若舞冯夷。</p><p class="poem-stanza">玄螭虫象并出进兮，形蟉虯而逶蛇。</p><p class="poem-stanza">雌蜺便娟以增挠兮，鸾鸟轩翥而翔飞。</p><p class="poem-stanza">音乐博衍无终极兮，焉乃逝以徘徊。</p><p class="poem-stanza">舒并节以驰骛兮，逴绝垠乎寒门。</p><p class="poem-stanza">轶迅风于清源兮，从颛顼乎增冰。</p><p class="poem-stanza">历玄冥以邪径兮，乘间维以反顾。</p><p class="poem-stanza">召黔赢而见之兮，为余先乎平路。</p><p class="poem-stanza">经营四方兮，周流六漠。</p><p class="poem-stanza">上至列缺兮，降望大壑。</p><p class="poem-stanza">下峥嵘而无地兮，上寥廓而无天。</p><p class="poem-stanza">视倏忽而无见兮，听惝恍而无闻。</p><p class="poem-stanza">超无为以至清兮，与泰初而为邻。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
